(()=>{
const previous=render;
let filters={from:'',to:'',employee:'',branch:''};
const safe=v=>esc(String(v??''));
function pageView(){
if(!nodeUser)return;const canEdit=['admin','manager'].includes(nodeUser.role);
const nav=document.querySelector('#nav');
if(nav&&!nav.querySelector('[data-shiftplanner]')){const button=document.createElement('button');button.dataset.shiftplanner='1';button.innerHTML='<i>'+navIcon('shift-planner')+'</i> '+(canEdit?'جدول شفتات الموظفين':'جدول شفتاتي');button.onclick=()=>{page='shift-planner';render()};nav.append(button)}
if(page!=='shift-planner')return;
const staff=(db.staff||[]).filter(s=>nodeUser.role==='admin'||(nodeUser.role==='manager'?s.branch===nodeUser.branch&&s.department===positions[nodeUser.position]:Number(s.id)===Number(nodeUser.id)));
const shifts=(db.shiftAssignments||[]).filter(x=>staff.some(s=>Number(s.id)===Number(x.employeeId))).slice().sort((a,b)=>(a.day+a.start).localeCompare(b.day+b.start));
const punches=db.punches||[];
const labels={late:'متأخر',on_time:'في الموعد',upcoming:'لم تبدأ الوردية',overdue:'تنبيه: لم يسجل حضور',missing:'انتهت الوردية دون سجل حضور',invalid:'موعد غير صالح بتوقيت القاهرة'};
const filtered=shifts.filter(s=>(!filters.from||s.day>=filters.from)&&(!filters.to||s.day<=filters.to)&&(!filters.employee||Number(s.employeeId)===Number(filters.employee))&&(!filters.branch||s.branch===filters.branch));
const rows=EnergyAttendance.rows(shifts,punches).filter(r=>filtered.includes(r.s)).map(r=>({x:r.s,state:labels[r.status],late:r.punch?String(r.late)+' دقيقة':'—',status:r.status}));
const app=document.querySelector('#app');if(!app)return;
app.innerHTML='<section class="shiftplanner" dir="rtl"><p>ENERGY CLUB · SHIFTS</p><h2>جدول شفتات الموظفين</h2><p>كل وردية مرتبطة بموظف وفرع وتاريخ. البريك مدفوع ولا يؤثر على أجر الساعات.</p><form id="shift-report-filters" class="toolbar"><label>من<input name="from" type="date" value="'+safe(filters.from)+'"></label><label>إلى<input name="to" type="date" value="'+safe(filters.to)+'"></label><label>الموظف<select name="employee"><option value="">الكل</option>'+staff.map(s=>'<option value="'+safe(s.id)+'" '+(String(s.id)===filters.employee?'selected':'')+'>'+safe(s.name)+'</option>').join('')+'</select></label><label>الفرع<select name="branch"><option value="">الكل</option>'+[...new Set(staff.map(s=>s.branch))].map(b=>'<option '+(b===filters.branch?'selected':'')+'>'+safe(b)+'</option>').join('')+'</select></label><button>عرض التقرير</button></form><div class="shiftplanner-tools"><button id="shiftplanner-add" '+(!canEdit?'hidden':'')+'>＋ تعيين شفت</button><button id="shiftplanner-csv">↓ تصدير تقرير CSV لفتحه في Excel</button></div><div class="shiftplanner-scroll"><table><thead><tr><th>الموظف</th><th>الفرع</th><th>التاريخ</th><th>الوقت</th><th>الحضور</th><th>التأخير المسجل</th><th>إجراء</th></tr></thead><tbody>'+rows.map(({x,state,late})=>'<tr><td>'+safe(x.employeeName)+'</td><td>'+safe(x.branch)+'</td><td>'+safe(x.day)+'</td><td>'+safe(x.start)+' — '+safe(x.end)+'</td><td>'+safe(state)+'</td><td>'+safe(late)+'</td><td><button data-shift-delete="'+safe(x.id)+'">حذف</button></td></tr>').join('')+'</tbody></table></div><p>حالة التأخير محسوبة من حضور مسجل؛ التنبيهات داخل التطبيق تتجدد من البيانات المحفوظة عند التحديث. عدم وجود سجل ليس اعتماد غياب ولا يسبب خصمًا تلقائيًا.</p></section>';
document.querySelector('#shift-report-filters').onsubmit=e=>{e.preventDefault();const next=Object.fromEntries(new FormData(e.target));if(next.from&&next.to&&next.from>next.to)return toast('راجع ترتيب تواريخ التقرير');filters=next;render()};
app.querySelectorAll('[data-shift-delete]').forEach(b=>b.hidden=!canEdit);
document.querySelector('#shiftplanner-add').onclick=()=>{
if(!canEdit)return;
if(!staff.length)return toast('لا يوجد موظفون متاحون في نطاق إدارتك');
openForm('تعيين شفت للموظف','<label>الموظف<select name="employeeId">'+staff.map(s=>'<option value="'+safe(s.id)+'">'+safe(s.name)+' — '+safe(s.branch)+'</option>').join('')+'</select></label><label>اليوم<input type="date" name="day" required></label><label>البداية<input type="time" name="start" required></label><label>النهاية<input type="time" name="end" required></label><label>تكرار حتى (اختياري)<input name="to" type="date"></label><label>أيام التكرار<select name="repeatMode"><option value="daily">كل الأيام</option><option value="weekly">نفس يوم الأسبوع</option><option value="workdays">السبت إلى الخميس</option></select></label><p>الحد الأقصى للتكرار ٣١ يومًا. التعارض يرفض المجموعة بالكامل.</p><label>سماح التأخير بالدقائق<input name="graceMinutes" type="number" min="0" max="120" value="0" required></label><p>يمكن اختيار وقت نهاية أقل من البداية للورديات الليلية.</p>',()=>{});
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));if(values.to){const weekday=new Date(values.day+'T12:00:00Z').getUTCDay();values.weekdays=values.repeatMode==='weekly'?[weekday]:values.repeatMode==='workdays'?[0,1,2,3,4,6]:[0,1,2,3,4,5,6];}await nativeAction(values.to?'shift_repeat':'shift_assign',values);document.querySelector('#modal').close();toast('تم حفظ الشفت على السيرفر')}catch(err){toast(err.message)}};
};
app.querySelectorAll('[data-shift-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('حذف هذا الشفت؟'))return;try{await nativeAction('shift_remove',{id:b.dataset.shiftDelete})}catch(err){toast(err.message)}});
document.querySelector('#shiftplanner-csv').onclick=()=>{const q=v=>'"'+String(v??'').replace(/^[=+\-@]/,' $&').replace(/"/g,'""')+'"';const lines=[['الموظف','الفرع','اليوم','بداية الشفت','نهاية الشفت','الحضور','التأخير'],...rows.map(({x,state,late})=>[x.employeeName,x.branch,x.day,x.start,x.end,state,late])].map(row=>row.map(q).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='energy-shifts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};
}
render=function(){const target=page;if(target==='shift-planner')page='overview';previous();page=target;pageView()};
const css=document.createElement('style');css.textContent='.shiftplanner{direction:rtl;background:#171813;color:#f5edda;border:1px solid #947341;border-radius:22px;padding:25px}.shiftplanner h2{color:#e7c77b;font-size:30px}.shiftplanner p{color:#c9bd9e}.shiftplanner-tools{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.shiftplanner button{background:#d7b56d;color:#191a14;border-radius:30px;padding:10px 14px;border:0;cursor:pointer}.shiftplanner-scroll{overflow:auto}.shiftplanner table{min-width:730px;width:100%;border-collapse:collapse}.shiftplanner th,.shiftplanner td{text-align:right;border-bottom:1px solid #58503a;padding:12px}';document.head.append(css);
})();